def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([5, 5, 5]), fmt([3, 2, 1]), fmt([1, 2, 3, 4]), fmt([7, 2, 2, 2]), fmt([4, 3, 2, 6]),
             fmt([100000, 1, 1, 1, 100000]), fmt([2, 1, 3, 2])]
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for vmax in (3, 10, 30):
            tests.append(fmt([rng.randint(1, vmax) for _ in range(n)]))
    N = 10 ** 5
    tests.append(fmt([rng.randint(1, 10 ** 5) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 3) for _ in range(N)]))
    tests.append(fmt([1] * N))
    tests.append(fmt([max(1, 10 ** 5 - i // 2) for i in range(N)]))
    tests.append(fmt([rng.randint(1, 10) if rng.random() < 0.5 else rng.randint(1, 10 ** 5) for _ in range(N)]))
    return tests

